	public class ShockTouchBasic : MeleeAttackState
	{
		public new static string staticID = "ShockTouchBasic";

		private ShockTouchObject shockTouchObj;

		private Vector2 attackPos;

		public ShockTouchBasic(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			isBasic = true;
			isMeleeSkill = true;
			attackPrefab = ShockTouchObject.Prefab;
			destroyAttackObjectOnExit = false;
			setParent = false;
			maxComboCount = 4;
			animStartTime = 0.25f;
			animExecTime = 0.3f;
			baseCancelThreshold = 0.4f;
			finalCancelThreshold = 0.6f;
			baseRunThreshold = 0.8f;
			finalRunThreshold = 0.9f;
			baseExitThreshold = 1f;
			finalExitThreshold = 1.15f;
			flipObjectForBackhand = false;
			attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 12f, 10, VarStatModType.OverrideWithMods);
			finalAttackMoveSpeedMod = attackMoveSpeedMod;
			autoHoldStat.BaseValue = true;
		}

		public override void ExecuteAttack()
		{
			base.ExecuteAttack();
			parent.movement.EndMovement();
			attackPos = parent.attackOriginTrans.position;
			currentAttackObject.transform.position = attackPos + inputVector;
			PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningCompactTrail").Emit(attackPos, attackPos - inputVector * 0.5f);
			shockTouchObj = (ShockTouchObject)currentAttackObject;
			shockTouchObj.useBurst = calcComboCounter == 0;
			shockTouchObj.isEmpowered = IsEmpowered;
			shockTouchObj.attackVec = inputVector;
		}
	}

