	public class BoltRailBasic : MeleeAttackState
	{
		public new static string staticID = "BoltRailBasic";

		private static string burstSkillID = "LightningBurstBasic";

		private BoltRail currentRail;

		public BoltRailBasic(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			isBasic = true;
			attackPrefab = BoltRail.Prefab;
			destroyAttackObjectOnExit = false;
			updateSkillLevel = false;
			maxComboCount = 5;
			animStartTime = 0.3f;
			animExecTime = 0.35f;
			baseCancelThreshold = 0.45f;
			finalCancelThreshold = 0.65f;
			baseRunThreshold = 0.85f;
			finalRunThreshold = 0.9f;
			baseExitThreshold = 1f;
			finalExitThreshold = 1.1f;
			flipObjectForBackhand = false;
			attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 0.125f, 10, VarStatModType.OverrideWithMods);
			finalAttackMoveSpeedMod = attackMoveSpeedMod;
			autoHoldStat.BaseValue = true;
			sfxNames = new string[maxComboCount];
			for (int i = 0; i < maxComboCount; i++)
			{
				sfxNames[i] = "BoltRailBasic";
			}
		}

		public override void PlayAnimation(int attackCount)
		{
			parent.anim.PlayDirectional((attackCount != maxComboCount) ? parent.ForehandAnimStr : parent.BackhandAnimStr, -1, animStartTime);
		}

		public override void HandleComboCount(int attackCount)
		{
			base.HandleComboCount(attackCount);
			if (calcComboCounter == 0 && currentAttackObject != null)
			{
				currentRail = currentAttackObject as BoltRail;
				currentRail.addLightningBurst = true;
				currentRail.category = parent.skillCategory;
				currentRail.burstSkillID = burstSkillID;
				currentRail.isEmpowered = IsEmpowered;
			}
			else if (calcComboCounter == maxComboCount - 1)
			{
				CameraController.ShakeCamera(0.2f);
			}
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("LightningStart");
			int? particleCount = 1;
			Vector3? position = (Vector2)parent.attackOriginTrans.position + inputVector;
			Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
			poolItem.Emit(particleCount, position, null, localEulerAngles);
		}
	}

