	public class ThunderOrbBasic : MeleeAttackState
	{
		public new static string staticID = "ThunderOrbBasic";

		private ThunderOrbProjectile currentTO;

		private bool useEmpowered;

		public ThunderOrbBasic(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			isBasic = true;
			isProjectileSkill = true;
			setParent = false;
			destroyAttackObjectOnExit = false;
			maxComboCount = 3;
			animStartTime = 0.2f;
			animExecTime = 0.3f;
			baseCancelThreshold = 0.45f;
			finalCancelThreshold = 0.55f;
			baseRunThreshold = 0.65f;
			finalRunThreshold = 0.7f;
			baseExitThreshold = 1f;
			finalExitThreshold = 1f;
			alwaysStartForehand = true;
			flipObjectForBackhand = false;
			attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 0.1f, 10, VarStatModType.OverrideWithMods);
			finalAttackMoveSpeedMod = attackMoveSpeedMod;
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			useEmpowered = IsEmpowered;
		}

		public override void ExecuteAttack()
		{
			HandleComboCount(comboCounter);
			HandleSelfTransition(comboCounter);
			AnnounceSkillExecuteEvent();
			CreateThunderOrb(parent.attackOriginTrans.position, inputVector);
		}

		private void CreateThunderOrb(Vector2 givenPosition, Vector2 givenVector)
		{
			currentTO = (ThunderOrbProjectile)Projectile.CreateProjectile(parent, ThunderOrbProjectile.Prefab, givenPosition + givenVector * 0.25f);
			currentTO.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentTO.attackBox.knockbackOverwriteVector = inputVector;
			currentTO.moveVector = inputVector;
			currentTO.UpdateCalculatedDamage(initDamageOverride: true);
			currentTO.burstLevel = (comboCounter + 1) % 6;
			if (useEmpowered)
			{
				currentTO.ricochet = true;
				currentTO.disableOnHit = false;
			}
		}
	}

using UnityEngine;

public class ShockTouchObject : MeleeAttackObject
{
	private static GameObject prefab;

	private static string burstSkillID = "LightningBurstBasic";

	private const float atkDelay = 0.15f;

	public bool isEmpowered;

	public bool useBurst;

	private Vector2 attackPos;

	private ChaosQuickStopwatch attackStopwatch = new ChaosQuickStopwatch(0.15f);

	private bool attackFinished;

	private CircleCollider2D circCol;

	private BoxCollider2D boxCol;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/ShockTouchObject.prefab"));

	public override void Awake()
	{
		base.Awake();
		circCol = attack.transform.GetComponent<CircleCollider2D>();
		boxCol = attack.transform.GetComponent<BoxCollider2D>();
	}

	public override void Start()
	{
		base.Start();
		if (isEmpowered)
		{
			attackStopwatch.SetDelay(0.075f);
		}
		attackStopwatch.IsRunning = true;
		attackPos = transform.position;
		circCol.enabled = true;
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, attackPos);
		PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Emit(2, attackPos, LightningAuraEffect.SmallLongAuraOverride);
		SoundManager.PlayAudioWithDistance("BallLightningLoop", transform.position, null, 24f, -1f, 1.1f);
	}

	private void FixedUpdate()
	{
		if (!attackFinished && !attackStopwatch.IsRunning)
		{
			if (useBurst)
			{
				useBurst = false;
				attackStopwatch.IsRunning = true;
				attack.SetAttackInfo(attack.atkInfo.skillCategory, burstSkillID, (!isEmpowered) ? 1 : 2);
				boxCol.enabled = true;
				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, attackPos);
				PoolManager.GetPoolItem<LightningBlastEffect>().Play(attackPos + attackVec, Globals.GetRotationVector(attackVec));
				SoundManager.PlayAudioWithDistance("BallLightningEnd", attackPos, null, 24f, -1f, 1.25f);
				CameraController.ShakeCamera(0.35f);
			}
			else
			{
				circCol.enabled = false;
				boxCol.enabled = false;
				attackFinished = true;
			}
		}
	}
}
