using UnityEngine;

public class ThunderOrbProjectile : Projectile
{
	private static GameObject prefab;

	private ParticleEffect lstEmitter;

	public int burstLevel = 2;

	private AttackInfo burstInfo;

	private float ricochetMoveSpeed = 32f;

	private bool burstCreated;

	private bool destroyQueued;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ThunderOrbProjectile.prefab"));

	public override void Start()
	{
		base.Start();
		lstEmitter = PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningSectionedTrail");
		lstEmitter.followTransform = transform;
		lstEmitter.reqFollowTrans = true;
		ParticleEffect particleEffect = lstEmitter;
		float? emissionRate = 10f;
		ParticleSystemOverride overrides = new ParticleSystemOverride
		{
			startRotation = Globals.GetRotationVector(moveVector).z + -90f,
			startLifetime = 0.12f
		};
		particleEffect.Play(emissionRate, null, overrides);
		burstInfo = attackBox.GetAtkInfoAtLevel(burstLevel);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, transform.position, LightningAuraEffect.SmallMedAuraOverride);
		SoundManager.PlayWithDistAndSPR("ThunderBounce", transform.position);
	}

	public override void ResetProjectile()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			Object.Destroy(gameObject, 0.25f);
			CreateBurst(transform.position);
			moveSpeed = 0f;
			moveVector = Vector2.zero;
			rotation = false;
			anim.Play("Explode", -1, 0f);
			StopEmitter();
		}
	}

	private void OnDestroy()
	{
		StopEmitter();
	}

	public override void UpdateCalculatedDamage(bool initDamageOverride = false)
	{
		base.UpdateCalculatedDamage(initDamageOverride);
		calculatedDamage = projectileStatData.GetValue<int>(StatData.damageStr, burstLevel);
	}

	public override void OnRicochet()
	{
		CreateBurst(transform.position);
		burstCreated = false;
		moveSpeed = ricochetMoveSpeed;
	}

	public override void HandleWallCollision(Collider2D other)
	{
		CreateBurst(transform.position);
		if (Projectile.globalProjectileWallCollisionEvents != null)
		{
			Projectile.globalProjectileWallCollisionEvents(this);
		}
		if (ricochetCounter >= ricochetAmount)
		{
			ChaosStopwatch.Stop(flyStopwatchID);
		}
		HandleCollision(other);
	}

	public override void HandleCollision(Collider2D other)
	{
		if (!(other.transform.parent != null) || IsParentObject(other.gameObject))
		{
			return;
		}
		if (disableOnHit || calculatedDamage == 0)
		{
			flagForReset = true;
		}
		else if (ricochet && ricochetAmount > 0)
		{
			ricochetCounter++;
			nextTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, ricochetRadius, playerTagOnly: false, null, other.transform.parent.gameObject, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
			if (nextTargetInfo == null || ricochetCounter >= ricochetAmount)
			{
				ChaosStopwatch.Stop(flyStopwatchID);
				ricochetCounter = 0;
				return;
			}
			OnRicochet();
			ChaosStopwatch.Refresh(flyStopwatchID, flyTime);
			moveVector = (nextTargetInfo.hurtBoxPosition - transform.position).normalized;
			isPointedAtMoveVector = false;
		}
	}

	private void CreateBurst(Vector2 givenPos)
	{
		if (!burstCreated)
		{
			burstCreated = true;
			LightningBurst.CreateBurst(givenPos, burstInfo).attack.knockbackOverwriteVector = moveVector;
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, givenPos, LightningAuraEffect.SmallMedAuraOverride);
			SoundManager.PlayWithDistAndSPR("BoltRailBasic", givenPos);
		}
	}

	private void StopEmitter()
	{
		if (lstEmitter != null)
		{
			lstEmitter.Stop();
			lstEmitter = null;
		}
	}
}
