using UnityEngine;

public class LightningBurst : ElementalBurst
{
	private static GameObject prefab;

	public static readonly string standardSkillID = "LightningBurst";

	public static readonly string floorSkillID = "LightningBurstFloor";

	private ParticleSystem partSys;

	private ParticleSystem.MainModule mainMod;

	public bool skipParticleEmit;

	public bool playAudio = true;

