	private Vector2 ionPosition;

	private Vector2 ionVector;

	private float ionDistance;

	private bool atkComplete;

	private LightningStream currentLS;

	private Vector2 targetLocation = Vector2.zero;

	private string skillCategory = string.Empty;

	private string skillID = string.Empty;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChainedDashOrb.prefab"));

	public void Start()
	{
		if (chainStopwatch == null)
		{
			(chainStopwatch = new ChaosQuickStopwatch(0.5f)).IsRunning = true;
		}
		SetIonVars();
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, spriteRenderer.transform.position);
		if (createAttack)
		{
			anim.Play("Idle", -1, 0f);
		}
		string audioID = "StaticCrackle";
		Vector2? soundOrigin = transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
	}

	public void Update()
	{
		if (!atkComplete && !chainStopwatch.IsRunning)
		{
			atkComplete = true;
			if (playerIDDict.ContainsKey(parentID))
			{
				hitCount = playerIDDict[parentID];
			}
			originPartSys.Stop();
			ionPartSys.Stop();
			if (createAttack)
			{
				CreateLightningStream();
			}
			if (parentChainList != null)
			{
				parentChainList.Remove(transform);
			}
			LightningBurst.CreateBurst(transform.position, string.Empty, string.Empty, 1, 0.5f);
			CameraController.ShakeCamera(0.5f);
			Object.Destroy(gameObject, (float)(hitCount + 1) * hitInterval);
		}
	}

	public static void SetHitCount(int givenID, int givenCount)
	{
		if (playerIDDict.ContainsKey(givenID))
		{
			playerIDDict[givenID] = givenCount;
		}
		else
		{
			playerIDDict.Add(givenID, givenCount);
		}
	}

	public void SetAttackVars(Vector2 givenLocation, string givenCategory, string givenID)
	{
		targetLocation = givenLocation;
		skillCategory = givenCategory;
		skillID = givenID;
	}

	private void SetIonVars()
	{
		if (!createAttack)
		{
			originPartSys.Play();
			ionPartSys.Stop();
			return;
		}
		currentPosition = transform.position;
		ionPosition = (currentPosition + targetLocation) * 0.5f;
		ionVector = targetLocation - currentPosition;
		ionDistance = ionVector.magnitude;
		if (ionDistance <= 0.1f || ionDistance > maxDistance)
		{
			createAttack = false;
			ionPartSys.Stop();
			return;
		}
		ionPartSys.transform.position = ionPosition;
		ionPartSys.transform.rotation = Globals.GetRotationQuaternion(Globals.GetPerpendicular(ionVector.normalized));
		ionEmitMod = ionPartSys.emission;
		ionEmitMod.rateOverTime = ionDistance * 3f;
		ionShapeMod = ionPartSys.shape;
		ionShapeMod.radius = ionDistance * 0.5f;
	}

	private void CreateLightningStream()
	{
		anim.Play("Stop");
		currentLS = Globals.ChaosInst<LightningStream>(LightningStream.Prefab, transform.parent, transform.position);
		currentLS.targetLocation = targetLocation;
		currentLS.attack.SetAttackInfo(skillCategory, skillID);
		currentLS.hitCount = hitCount;
		currentLS.hitInterval = hitInterval;
	}

	public void PlayLandEffect()
	{
		CameraController.ShakeCamera(0.2f);
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(6, spriteRenderer.transform.position);
	}
}
