		{
			base.ExecuteSkill();
			CameraController.ShakeCamera(0.2f);
			parent.StartCoroutine(ActivateBuff());
		}

		private IEnumerator ActivateBuff()
		{
			SetBuffStatus(givenStatus: true);
			durationStopwatch.IsRunning = true;
			parent.hud.castBar.StartCast(durationStopwatch.ID, givenStatus: false);
			while (durationStopwatch.IsRunning)
			{
				if (!whileStopwatch.IsRunning)
				{
					whileStopwatch.IsRunning = true;
					WhileBuffActive();
				}
				yield return null;
			}
			parent.hud.castBar.EndCast();
			StartCooldownTimer();
			SetBuffStatus(givenStatus: false);
		}

		public virtual void SetBuffDuration()
		{
			buffDuration = skillData.GetValue<float>(StatData.durStr);
		}

