		if (ChaosStopwatch.Check(durationStopwatchID))
		{
			destroyQueued = true;
			anim.Play("Release", -1, 0f);
			if (magAudio != null && magAudio.isPlaying)
			{
				magAudio.Stop();
			}
			SoundManager.PlayAudioWithDistance("BoltClaymore", transform.position);
		}
		else
		{
			magAudio = SoundManager.PlayIfNotPlaying("ElectricField", magAudio, transform, useStdPitchOverride: false);
		}
	}

	private void LateUpdate()
	{
		if (!destroyQueued && followTrans != null)
		{
			transform.position = followTrans.position;
		}
	}

	private bool OtherColIsNull(Collider2D other)
	{
		return other == null || other.transform == null || other.transform.parent == null;
	}

	private void OnTriggerStay2D(Collider2D other)
	{
		HandleBiasMoveVector(other);
	}

	private void OnTriggerEnter2D(Collider2D other)
	{
		if (!OtherColIsNull(other))
		{
			otherScript = other.transform.parent.GetComponent<Projectile>();
			if (!(otherScript == null) && !otherScript.ignoreNegate && !otherScript.forcedReturn && !(otherScript.parentObject == parentObject) && !(otherScript.attackBox == null) && otherScript.attackBox.atkInfo != null)
			{
				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, otherScript.transform.position);
				string audioID = "ImpactLightning";
				Vector2? soundOrigin = otherScript.transform.position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			}
		}
	}

	private void HandleBiasMoveVector(Collider2D other)
	{
		if (OtherColIsNull(other))
		{
			return;
		}
		otherScript = other.transform.parent.GetComponent<Projectile>();
		if (otherScript == null || otherScript.ignoreNegate || otherScript.forcedReturn || otherScript.parentObject == parentObject || otherScript.attackBox == null || otherScript.attackBox.atkInfo == null)
		{
			return;
		}
		otherAttackInfo = otherScript.attackBox.atkInfo;
		if (otherAttackInfo.isUltimate || (!GameController.pvpOn && otherAttackInfo.skillCategory.Contains("Player") && otherAttackInfo.skillCategory != skillCategory))
		{
			return;
		}
		currentPosition = transform.position;
		otherPosition = other.transform.position;
		otherDistance = Vector2.Distance(currentPosition, otherPosition) * invertedRadius;
		if (otherScript.ignoreReflect)
		{
			PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Large, otherPosition, otherPosition);
			otherScript.ForceProjectileToReturn();
			return;
		}
		if (!sparkTimer.IsRunning)
		{
			sparkTimer.SetDelay(Random.Range(0.05f, 0.15f));
			sparkTimer.IsRunning = true;
			if (Random.value > 0.5f)
			{
				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(2, otherScript.transform.position);
			}
		}
		otherScript.attackBox.damageModifier = damageModifier;
		if (GameController.pvpOn)
		{
			if (!otherAttackInfo.targetNames.Contains(Globals.allyHBStr))
			{
				otherAttackInfo.targetNames.Add(Globals.allyHBStr);
			}
		}
		else if (otherAttackInfo.targetNames.Contains(Globals.allyHBStr))
		{
			otherAttackInfo.targetNames.Remove(Globals.allyHBStr);
		}
		if (!otherAttackInfo.targetNames.Contains(Globals.enemyHBStr))
		{
			otherAttackInfo.targetNames.Add(Globals.enemyHBStr);
		}
		calcBiasValue = Mathf.Lerp(0.15f, 0.1f, otherDistance);
		directVector = (currentPosition - otherPosition).normalized;
		directVector = (Globals.GetPerpendicular(directVector) + directVector * Mathf.Lerp(0f, 0.75f, otherDistance)).normalized;
		otherScript.moveSpeed = Mathf.Lerp(16f, 12f, otherDistance);
		otherScript.moveVector = (otherScript.moveVector * (1f - calcBiasValue) + directVector * calcBiasValue).normalized;
		if (otherScript.pointTowardMoveVector)
		{
			otherScript.isPointedAtMoveVector = false;
		}
		otherScript.flyTime = 1f;
		otherScript.RefreshFlightTime();
		otherScript.parentObject = null;
		otherScript.parentEntity = null;
		otherAttackInfo.skillCategory = skillCategory;
		if (isEmpowered)
		{
			otherAttackInfo.shockChance = 1f;
		}
	}

	public void BreakEffect()
	{
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffectLarge").Emit(45, transform.position + new Vector3(0f, 1.25f, 0f), pSysOverride);
	}
}
