	public class UseShockNova : SkillState
	{
		public new static string staticID = "UseShockNova";

		private static int maxCharge = 5;

		private static int minCharge = 3;

		private float chargeTime = 0.25f;

		private int chargeStopwatchID;

		private float calcCastTime;

		private bool fullyCharged;

		private ChaosQuickStopwatch afterChargeStopwatch = new ChaosQuickStopwatch(0.25f);

		private string startAnimName;

		private ShockNova currentSN;

		private Vector2 spawnPosition;

		private const int ultCount = 4;

		private ShockNova[] ultNovaArray = new ShockNova[4];

		private Vector2 ultSpawnOffset;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public UseShockNova(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			disableStartCooldown = true;
			isHoldSkill = true;
			SetAnimTimes(0f, 0f, 0.3f, 0.8f, 0.9f);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			chargeTime = ((!IsEmpowered) ? 0.25f : 0.15f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			startAnimName = OnEnterAnimStr;
			parent.ToggleEnemyFloorCollisions(status: false);
			spawnPosition = parent.transform.position;
			if (isUltimate)
			{
				fullyCharged = true;
				for (int i = 0; i < 4; i++)
				{
					ultSpawnOffset = Globals.GetCirclePositionVector(4, i);
					ultNovaArray[i] = CreateShockNova(spawnPosition + ultSpawnOffset * 3.5f, useCastCircle: false);
					ultNovaArray[i].trailSeedVec = ultSpawnOffset;
					ultNovaArray[i].centerStrikePosition = spawnPosition + ultSpawnOffset * 2f;
				}
			}
			else
			{
				calcCastTime = (float)(maxCharge - minCharge) * chargeTime;
				parent.hud.castBar.StartCast(ChaosStopwatch.Begin(calcCastTime + 0.05f), givenStatus: true);
				fullyCharged = false;
				CreateShockNova(spawnPosition);
				chargeStopwatchID = ChaosStopwatch.Begin(chargeTime, useInterval: true, chargeTime, maxCharge - minCharge);
			}
		}

		public override void HandleHoldButton()
		{
			holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
			parent.anim.PlayDirectional(startAnimName, -1, animHoldTime);
			if (!fullyCharged)
			{
				switch (ChaosStopwatch.CheckInterval(chargeStopwatchID))
				{
				case StopwatchState.Ready:
					AddCharge();
					break;
				case StopwatchState.Done:
					fullyCharged = true;
					afterChargeStopwatch.IsRunning = true;
					break;
				}
			}
			else if (!afterChargeStopwatch.IsRunning)
			{
				afterChargeStopwatch.IsRunning = true;
				AddCharge();
			}
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			StartCooldownTimer();
			parent.anim.Play(startAnimName, -1, animExecTime);
			parent.hud.castBar.EndCast();
			if (currentSN != null)
			{
				currentSN.Detonate();
				currentSN = null;
			}
			if (!isUltimate)
			{
				return;
			}
			for (int i = 0; i < 4; i++)
			{
				if (ultNovaArray[i] != null)
				{
					ultNovaArray[i].Detonate();
					ultNovaArray[i] = null;
				}
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleEnemyFloorCollisions();
			parent.hud.castBar.EndCast();
			if (isUltimate)
			{
				for (int i = 0; i < 4; i++)
				{
					if (!(ultNovaArray[i] == null))
					{
						ultNovaArray[i].StopNova();
						ultNovaArray[i] = null;
					}
				}
			}
			else if (currentSN != null)
			{
				currentSN.StopNova();
				currentSN = null;
			}
			if (!skillExecuted)
			{
				StartCooldownTimer();
			}
		}

		private ShockNova CreateShockNova(Vector2 givenPosition, bool useCastCircle = true)
		{
			currentSN = ChaosInst<ShockNova>(ShockNova.Prefab, givenPosition);
			currentSN.attack.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
			currentSN.isEmpowered = IsEmpowered;
			if (isUltimate)
			{
				currentSN.maxCharge = maxCharge * 2;
				currentSN.currentCharge = maxCharge * 2;
				currentSN.castTime = 0f;
				currentSN.useCastingCircle = useCastCircle;
				currentSN.useSparseTrail = true;
			}
			else
			{
				currentSN.maxCharge = maxCharge;
				currentSN.currentCharge = minCharge;
				currentSN.castTime = calcCastTime;
			}
			return currentSN;
		}

		public void AddCharge()
		{
			if (currentSN != null)
			{
				currentSN.AddCharge();
			}
		}
	}

using System.Collections.Generic;
using UnityEngine;

public class ShockNova : MonoBehaviour
{
	private static GameObject prefab;

	[HideInInspector]
	public Attack attack;

	private Collider2D attackCollider;

	[HideInInspector]
	public float shockRadius = 4f;

	[HideInInspector]
	public bool isEmpowered;

	private float empoweredScale = 1.25f;

	[HideInInspector]
	public int maxCharge = 10;

	[HideInInspector]
	public int currentCharge;

	private static Color32 particleColor = new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, 204);

	private static Color32 particleColorInner = new Color32(byte.MaxValue, byte.MaxValue, byte.MaxValue, 153);

	[HideInInspector]
	public float castTime = 1f;

	[HideInInspector]
	public Color castColor;

	public bool useCastingCircle = true;

	private CastingCircle castingCircle;

	private ParticleEffect lightningField;

	private int hitStopwatchID;

	private float hitDelay = 0.1f;

	private int totalPositions = 8;

	private Vector2 spawnPosition;

	private List<Vector2> circlePositionList = new List<Vector2>();

	private int nextIndex;

	private bool isReleased;

	private bool fullyCharged;

	public bool playAudio = true;

	private int effectStopwatchID = -1;

	[HideInInspector]
	public bool useSparseTrail;

	[HideInInspector]
	public Vector2 trailSeedVec = Vector2.up;

	[HideInInspector]
	public Vector3 centerStrikePosition;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShockNova.prefab"));

	private float LerpValue => (float)currentCharge / (float)maxCharge;

	private void Awake()
	{
		attack = transform.Find("AttackBox").GetComponent<Attack>();
		attackCollider = attack.GetComponent<Collider2D>();
		castColor = CastingCircle.defaultColor;
		centerStrikePosition = transform.position;
	}

	private void Start()
	{
		if (isEmpowered)
		{
			shockRadius *= empoweredScale;
			transform.localScale *= empoweredScale;
		}
		spawnPosition = transform.position;
		if (isEmpowered)
		{
			totalPositions = 12;
		}
		for (int i = 0; i < totalPositions; i++)
		{
			circlePositionList.Add(spawnPosition + shockRadius * Globals.GetRotatedCircleVector(totalPositions, i, trailSeedVec));
		}
		if (useCastingCircle)
		{
			string animName = ((!(castTime > 0f)) ? "Spin" : "Draw");
			Vector3 position = transform.position;
			bool disableWithParentVal = false;
			Color? color = castColor;
			float drawTime = castTime;
			castingCircle = CastingCirclePool.Spawn(animName, position, disableWithParentVal, null, trackParentVal: true, useCastTimeVal: false, 0f, 0f, 0f, color, drawTime);
			castingCircle.SetUnitSize(0f - shockRadius, shockRadius);
		}
		lightningField = PoolManager.GetPoolItem<ParticleEffect>("LightningField");
		lightningField.Play(shockRadius * 4f, transform.position, new ParticleSystemOverride
		{
			radius = shockRadius
		});
	}

	private void FixedUpdate()
	{
		if (isReleased)
		{
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Running:
				attackCollider.enabled = true;
				break;
			case StopwatchState.Ready:
				attackCollider.enabled = false;
				CreateShockEffect();
				break;
			case StopwatchState.Done:
				StopEffects();
				Object.Destroy(gameObject);
				break;
			}
		}
		else if (ChaosStopwatch.Check(effectStopwatchID))
		{
			effectStopwatchID = ChaosStopwatch.Begin(Random.Range(0.125f, 0.5f));
			CreateShockEffect();
		}
	}

	public void AddCharge(int givenCount = 1)
	{
		currentCharge = Mathf.Min(currentCharge + givenCount, maxCharge);
	}

	public void Detonate()
	{
		CameraController.ShakeCamera(0.8f);
		SoundManager.PlayAudioWithDistance("ThunderClap", transform.position);
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitDelay, currentCharge + 1);
		if (currentCharge == maxCharge)
		{
			fullyCharged = true;
			attack.ChangeAttackInfoLevel(2);
		}
		StopEffects();
	}

	public void StopNova()
	{
		StopEffects();
		ChaosStopwatch.Stop(hitStopwatchID);
	}

	private void StopEffects()
	{
		isReleased = true;
		if (castingCircle != null)
		{
			castingCircle.Reset();
			castingCircle = null;
		}
		if (lightningField != null)
		{
			lightningField.Stop();
			lightningField = null;
		}
	}

	private void CreateShockEffect()
	{
		if (isReleased)
		{
			for (int i = 0; i < totalPositions; i++)
			{
				nextIndex = (i + 1) % totalPositions;
				CreateTrail(circlePositionList[i], circlePositionList[nextIndex]);
				if (!useSparseTrail || (i + 1) % 2 == 0)
				{
					CreateTrail(circlePositionList[i], spawnPosition, useInnerColor: true);
				}
			}
			if (fullyCharged)
			{
				Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, transform, centerStrikePosition).playAudio = playAudio;
			}
			if (playAudio)
			{
				string audioID = "BallLightningEnd";
				Vector2? soundOrigin = transform.position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			}
		}
		else if (playAudio)
		{
			SoundManager.PlayAudioWithDistance("BallLightningLoop", transform.position, null, 24f, -1f, 1.2f);
		}
	}

	private void CreateTrail(Vector2 givenStart, Vector2 givenEnd, bool useInnerColor = false)
	{
		SectionedTrailEmitter poolItem = PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine");
		Color32? startColor = ((!useInnerColor) ? particleColor : particleColorInner);
		poolItem.Emit(givenStart, givenEnd, -1, emitEveryOther: false, -1f, snapToFit: true, -1f, 0f, startColor, useEndEmitter: false, null, "Shadow");
	}
}

