	private IEnumerator CreateThunderField(Vector2 givenPosition)
	{
		int ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.0625f, 12);
		int ultCounter = 0;
		bool ultInProgress = true;
		int[] ultArr = new int[6] { 0, 1, 2, 3, 4, 5 };
		int ultIndex = 0;
		ultArr.Shuffle();
		while (ultInProgress)
		{
			switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
			{
			case StopwatchState.Ready:
				if (ultCounter < 6)
				{
					CreateThunderJavelin(Globals.GetSafeLinecastVector(givenPosition, Globals.GetCirclePositionVector(12, ultArr[ultCounter] * 2 + 1), 2f, ChaosCollisions.layerAllWallAndObst));
