	public override void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (!lifeStopwatch.IsRunning)
		{
			destroyQueued = true;
			if (gameObject != null)
			{
				Object.Destroy(gameObject, destroyTime);
			}
		}
		else if (throwComplete)
		{
			if (useSecondaryBurst && !burstStopwatch.IsRunning)
			{
				useSecondaryBurst = false;
				Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, null, currentPosition);
				LightningBurst.CreateBurst(currentPosition, skillCat, skillID, skillLev + 1, burstRadius, isUltimate);
