			}
		}
		else
		{
			base.FixedUpdate();
		}
	}

	public override void Update()
	{
		if (!destroyQueued && delayStarted && ChaosStopwatch.Check(delayStopwatchID))
		{
			delayStarted = false;
			ChaosStopwatch.Resume(flightStopwatchID);
		}
	}

	private void LateUpdate()
	{
		if (!throwComplete && spriteRenderer != null)
		{
			spriteRenderer.sortingLayerName = ((!(heightLerpValue > 2f)) ? "Actor" : "UI");
