		skillLev = givenLev;
		isUltimate = givenUlt;
		throwHeight = givenStart;
		ForceNewHeights(givenStart, givenEnd);
		ThrowToTargetVector(givenTarget);
		if (delayTime > 0f)
		{
			delayStarted = true;
			delayStopwatchID = ChaosStopwatch.Begin(delayTime);
			ChaosStopwatch.Pause(flightStopwatchID);
			anim.Play("Form", -1, 0f);
		}
	}

	public override void InitThrow()
	{
		base.InitThrow();
		if (spriteTrans != null)
		{
			currentPosition = transform.position + spriteStartPosition;
			calcRoteVector = new Vector2(Mathf.Clamp((targetPosition.x - currentPosition.x) * 0.25f, -1f, 1f), -1f).normalized;
			spriteTrans.localEulerAngles = Globals.GetRotationVector(calcRoteVector);
		}
		if (spriteRenderer != null)
		{
			spriteRenderer.enabled = true;
			spriteRenderer.sortingLayerName = "UI";
		}
	}

	public override void OnLanding()
	{
		base.OnLanding();
		currentPosition = transform.position;
		LightningBurst.CreateBurst(currentPosition, skillCat, skillID, skillLev, landRadius, isUltimate);
		PoolManager.GetPoolItem<ParticleEffect>("BurnMarkXSmallEmitter").Emit(1, currentPosition);
		SoundManager.PlayWithDistAndSPR("IonSpike", currentPosition);
		if (!Globals.CheckCircle(currentPosition, 0.25f, ChaosCollisions.layerPit))
		{
			lifeStopwatch.IsRunning = false;
			destroyTime = 0f;
			return;
		}
		if (!useSecondaryBurst)
		{
			lifeStopwatch.IsRunning = false;
			anim.Play("Fade", -1, 0f);
			destroyTime = 0.25f;
			return;
		}
		destroyTime = 0f;
		burstStopwatch.IsRunning = true;
		if (spriteRenderer != null)
		{
			spriteRenderer.sortingLayerName = "Actor";
		}
		PoolManager.GetPoolItem<ParticleEffect>("LightningField").Play(20f, currentPosition, new ParticleSystemOverride
		{
			radius = burstRadius - 0.25f
		}, burstStopwatch.Delay);
		lightningAuraEmitter.SetActive(value: true);
		lightningEmitter.SetActive(value: true);
		lightningEmitter.transform.localEulerAngles = -spriteTrans.localEulerAngles;
		CameraController.ShakeCamera(0.25f);
	}
}
