				localEulerAngles = (inputVector - prependVec * 0.12f).normalized;
				CreateLightningStream(givenPosition, givenCount, LightningStreamType.Default, emitParticles: true, localEulerAngles);
				givenPosition = atkPosition + prependVec * 0.15f - inputVector * 0.25f;
				givenCount = streamHitCount;
				localEulerAngles = (inputVector + prependVec * 0.3f).normalized;
				CreateLightningStream(givenPosition, givenCount, LightningStreamType.Default, emitParticles: true, localEulerAngles);
				givenPosition = atkPosition - prependVec * 0.15f - inputVector * 0.25f;
