				CreateLightningStream(atkPosition, calcHitCount, LightningStreamType.Default, emitParticles: false);
			}
		}
	}

	private void CreateLightningStrike(int givenIndex, Vector2 givenPosition, Vector2 givenVector)
	{
		lightStrikesArr[givenIndex] = ChaosInst<LightningStrike>(LightningStrike.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
		lightStrikesArr[givenIndex].anim.Play("Loop", -1, 0f);
		lightStrikesArr[givenIndex].spriteRenderer.sortingLayerName = "TargetLineAir";
	}

	private LightningStream CreateLightningStream(Vector2 givenPosition, int givenCount, LightningStreamType streamType = LightningStreamType.Default, bool emitParticles = true, Vector3? targetVec = null)
	{
		currentLS = ChaosInst<LightningStream>(LightningStream.Prefab, givenPosition - inputVector * 0.25f, targetVec.HasValue ? Globals.GetRotationQuaternion(targetVec.Value) : Globals.GetRotationQuaternion(inputVector));
		currentLS.targetLocation = Globals.GetLinecastVector(givenPosition, givenPosition + ((!targetVec.HasValue) ? inputVector : (((Vector2?)targetVec) ?? default(Vector2))) * streamRange, ChaosCollisions.layerUpperWall);
		currentLS.hitCount = givenCount;
		currentLS.hitInterval = 0.1f;
		currentLS.attack.SetAttackInfo(parent.skillCategory, skillID, (!isUltimate) ? 2 : 3, isUltimate);
		currentLS.attack.knockbackOverwriteVector = inputVector;
		currentLS.emitParticles = emitParticles;
		currentLS.streamType = streamType;
		if (streamType == LightningStreamType.Default)
		{
			currentLS.useEndEmitter = true;
		}
		if (givenCount > 1)
		{
			currentLS.attackWidth = 1.2f;
		}
