using UnityEngine;

public class PiercingShock : MonoBehaviour
{
	private static GameObject prefab;

	private ParticleEffect auraEffect;

	public Animator anim;

	public Attack attack;

	public bool destroyQueued;

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(5f);

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/PiercingShock.prefab"));

	private void Start()
	{
		lifeStopwatch.IsRunning = true;
		auraEffect = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		auraEffect.reqFollowTrans = true;
		auraEffect.Play(25f, followTransform: transform, position: null, overrides: ParticleEffectOverrides.WorldSpaceOverride);
		string audioID = "BallLightningEnd";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(1.15f, 1.25f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}

	private void Update()
	{
		if (!destroyQueued && !lifeStopwatch.IsRunning)
		{
			Reset();
		}
	}

	public void Reset()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			anim.Play("NeedleBreak", -1, 0f);
			if (auraEffect != null)
			{
				auraEffect.Stop();
			}
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, transform.position);
			string audioID = "BallLightningEnd";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 0.25f);
			}
		}
	}
}
	public class TeleStrikeState : SkillState
	{
		public class TSHVars
		{
			public GameObject atkObj;

			public Animator atkAnim;

			public Vector2 lastPos;

			public Vector2 nextPos;

			public int animIndex;

			public int stopwatchID;

			public TSHVars(Vector2 givenPos, float givenDelay, int givenCount, float givenTime)
			{
				lastPos = givenPos;
				nextPos = Vector3.zero;
				animIndex = UnityEngine.Random.Range(0, 4);
				stopwatchID = ChaosStopwatch.Begin(UnityEngine.Random.Range(givenTime, givenDelay), useInterval: true, givenDelay, givenCount);
			}
		}

		public new static string staticID = "TeleStrike";

		private static GameObject tsPrefab;

		private bool playerMarkerStatus;

		private List<GameObject> targetsInArea;

		private GameObject targetObj;

		private Entity targetEntity;

		private Vector3 targetPosition;

		private static int ultCloneCount = 5;

		private List<TSHVars> tshList;

		private static float atkRange = 9f;

		private static float hitInterval = 0.1f;

		private int hitCount = 4;

		private Vector2 startPosition;

		private Vector2 endPosition;

		private Vector2 atkStartPos;

		private Vector2 currentPosition;

		private bool atkStarted;

		private bool atkCompleted;

		private bool targetHit;

		private bool retCompleted;

		private float moveLerpValue;

		private ChaosQuickStopwatch dashStopwatch = new ChaosQuickStopwatch(0.125f);

		private ChaosQuickStopwatch endStopwatch = new ChaosQuickStopwatch(0.15f);

		private Attack currentAtk;

		private BoolVarStatMod airborneStatMod;

		public TeleStrikeState(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			isMeleeSkill = true;
			isMovementSkill = true;
			airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 1);
			tshList = new List<TSHVars>();
			if (tsPrefab == null)
			{
				tsPrefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/TeleStrike.prefab");
			}
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			hitCount = ((!IsEmpowered) ? 4 : 6);
		}

		public override void OnEnter()
		{
			BaseOnEnter();
			inputVector = GetInputVector();
			parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, 0.5f);
			atkStarted = false;
			atkCompleted = false;
			targetHit = false;
			retCompleted = false;
			startPosition = parent.transform.position;
			endPosition = Globals.GetLinecastVector(startPosition, startPosition + inputVector * 6f, ChaosCollisions.layerAllWallAndObst);
		}

		public override void Update()
		{
			if (!targetHit)
			{
				return;
			}
			currentPosition = parent.transform.position;
			if (atkCompleted)
			{
				if (!retCompleted)
				{
					moveLerpValue = endStopwatch.TimePercentage;
					parent.rigidbody2D.MovePosition(Vector2.Lerp(endPosition, startPosition, moveLerpValue));
					retCompleted = moveLerpValue >= 1f;
				}
				else
				{
					parent.FaceTarget(currentPosition - inputVector);
					parent.movement.dashVector = -inputVector;
					parent.movement.moveVector = -inputVector;
					parent.movement.MoveToMoveVector();
					fsm.ChangeState(SlideState.staticID);
				}
				return;
			}
			atkCompleted = true;
			for (int i = 0; i < tshList.Count; i++)
			{
				switch (ChaosStopwatch.CheckInterval(tshList[i].stopwatchID))
				{
				case StopwatchState.Running:
					atkCompleted = false;
					break;
				case StopwatchState.Ready:
					targetPosition = GetTargetPosition(currentPosition, atkRange);
					if (!(targetPosition == Vector3.zero))
					{
						SpawnNewTeleStrike(tshList[i], targetPosition);
						atkCompleted = false;
					}
					break;
				}
			}
			if (atkCompleted)
			{
				endStopwatch.IsRunning = true;
				SoundManager.PlayAudioWithDistance("BallLightningEnd", atkStartPos);
			}
		}

		public override void FixedUpdate()
		{
			if (targetHit)
			{
				return;
			}
			if (!atkStarted)
			{
				if (parent.anim.AnimPlayed(0.75f) || IsEmpowered)
				{
					atkStarted = true;
					atkStartPos = parent.attackOriginTrans.position;
					base.ExecuteSkill();
					currentAtk = ChaosInst<Attack>(Attack.CirclePrefab, atkStartPos, Globals.GetRotationQuaternion(inputVector));
					currentAtk.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
					Attack attack = currentAtk;
					attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
					Attack attack2 = currentAtk;
					attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
					dashStopwatch.IsRunning = true;
					ToggleObjects(status: false);
					parent.dustEmitter.EmitCircle(80, 0.5f);
					PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, atkStartPos);
					SoundManager.PlayAudioWithDistance("TeleStrike", atkStartPos, null, 24f, -1f, 0.85f);
					SoundManager.PlayAudioWithDistance("BallLightningEnd", atkStartPos);
					CameraController.ShakeCamera(0.25f);
				}
			}
			else if (dashStopwatch.IsRunning)
			{
				parent.rigidbody2D.MovePosition(Vector2.Lerp(startPosition, endPosition, dashStopwatch.TimePercentage));
				if (currentAtk != null)
				{
					currentAtk.transform.position = parent.attackOriginTrans.position;
				}
			}
			else
			{
				PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(atkStartPos, parent.attackOriginTrans.position);
				parent.movement.dashVector = inputVector;
				fsm.ChangeState(SlideState.staticID);
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.playerMarker.ReleasePositionLock(!playerMarkerStatus);
			ToggleObjects(status: true);
			atkStartPos = parent.attackOriginTrans.position;
			foreach (TSHVars tsh in tshList)
			{
				PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(tsh.nextPos, atkStartPos);
			}
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(7, atkStartPos);
			tshList.Clear();
			parent.playerSummonsList.RemoveNullValues();
			CleanUpAtkObj();
		}

		public void OnTargetHit(Entity givenEnt)
		{
			if (targetHit || givenEnt == null || givenEnt is Destructible)
			{
				return;
			}
			targetHit = true;
			CleanUpAtkObj();
			endPosition = parent.transform.position;
			PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(atkStartPos, givenEnt.hurtBoxTransform.position);
			tshList.Clear();
			playerMarkerStatus = parent.playerMarker.isActive;
			parent.playerMarker.SetLockPosition(startPosition);
			if (isUltimate)
			{
				SetSkillLevel(2);
				for (int i = 0; i < ultCloneCount; i++)
				{
					tshList.Add(new TSHVars(endPosition, hitInterval, hitCount - 1, 0f));
				}
			}
			else
			{
				SetSkillLevel(1);
				tshList.Add(new TSHVars(endPosition, hitInterval, hitCount, hitInterval));
			}
		}

		private Vector3 GetTargetPosition(Vector3 givenPosition, float givenRange)
		{
			targetsInArea = Entity.GetAllTargetsInRange(GameController.enemies, givenPosition, givenRange, playerTagOnly: false, parent.playerSummonsList, parent.gameObject, requireLOS: true, ChaosCollisions.layerUpperWall);
			if (targetsInArea.Count > 0)
			{
				targetObj = targetsInArea[UnityEngine.Random.Range(0, targetsInArea.Count)];
				targetEntity = targetObj.GetComponent<Entity>();
				if (targetEntity != null && targetEntity.hurtBoxTransform != null)
				{
					return targetEntity.hurtBoxTransform.position;
				}
			}
			return Vector3.zero;
		}

		public void SpawnNewTeleStrike(TSHVars givenVar, Vector3 givenPosition)
		{
			if (givenVar.nextPos != Vector2.zero)
			{
				givenVar.lastPos = givenVar.nextPos;
			}
			givenVar.atkObj = UnityEngine.Object.Instantiate(tsPrefab, parent.hurtBoxTransform.position, Quaternion.identity, parent.playerObjTrans);
			parent.playerSummonsList.Add(givenVar.atkObj);
			givenVar.atkAnim = givenVar.atkObj.GetComponent<Animator>();
			givenVar.atkObj.transform.Find("Sprite").GetComponent<SpriteRenderer>().material.SetFloat("_PaletteIndex", parent.outfitColorIndex);
			givenVar.atkObj.GetComponentInChildren<Attack>().SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
			givenVar.nextPos = givenPosition;
			givenVar.atkObj.transform.position = givenPosition;
			switch (givenVar.animIndex)
			{
			case 0:
				givenVar.atkAnim.Play("SlashUp");
				givenVar.nextPos += new Vector2(0f, -1f);
				givenVar.atkObj.transform.position += new Vector3(0f, -0.25f, 0f);
				break;
			case 1:
				givenVar.atkAnim.Play("SlashDown");
				givenVar.nextPos += new Vector2(0f, 1f);
				givenVar.atkObj.transform.position += new Vector3(0f, 0.25f, 0f);
				break;
			case 2:
				givenVar.atkAnim.Play("SlashRight");
				givenVar.nextPos += new Vector2(-1.5f, 0f);
				givenVar.atkObj.transform.position += new Vector3(-0.25f, 0f, 0f);
				break;
			case 3:
				givenVar.atkAnim.Play("SlashLeft");
				givenVar.nextPos += new Vector2(1.5f, 0f);
				givenVar.atkObj.transform.position += new Vector3(0.25f, 0f, 0f);
				break;
			}
			givenVar.animIndex = (givenVar.animIndex + UnityEngine.Random.Range(1, 4)) % 4;
			PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(givenVar.lastPos, givenVar.nextPos);
			SoundManager.PlayAudioWithDistance("BallLightningLoop", givenVar.lastPos);
		}

		private void ToggleObjects(bool status)
		{
			parent.spriteRenderer.gameObject.SetActive(status);
			parent.shadowSprite.gameObject.SetActive(status);
			parent.spriteTrail.Toggle(status && parent.overdriveReady);
			parent.hurtBoxObj.SetActive(status);
			parent.floorContact.SetActive(status);
			parent.TogglePreventFallCollider(status);
			parent.airborneStat.Modify(airborneStatMod, !status);
		}

		private void CleanUpAtkObj()
		{
			if (currentAtk != null)
			{
				Attack attack = currentAtk;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
				UnityEngine.Object.Destroy(currentAtk.gameObject);
				currentAtk = null;
			}
		}
	}

