using UnityEngine;

public class VoltSplinterProjectile : Projectile
{
	private static GameObject prefab;

	public Transform followTrans;

	private float orbitRadiusSquared;

	private Vector2 distanceVector;

	private bool isOrbiting;

	public Movement movement;

	public bool clockwiseOrbit = true;

	private bool targetHit;

	private static AudioSource spinAudio;

	public Transform trailTrans;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/VoltSplinterProjectile.prefab"));

	public override void Awake()
	{
		base.Awake();
		movement = GetComponent<Movement>();
	}

	public override void Start()
	{
		base.Start();
		if (followTrans != null)
		{
			movement.InitOrbitAngle((transform.position - followTrans.position).normalized, clockwiseOrbit);
			PlaySpinAudio();
		}
		orbitRadiusSquared = movement.orbitRadius * movement.orbitRadius;
		isOrbiting = true;
	}

	public override void FixedUpdate()
	{
		if (targetHit)
		{
			base.FixedUpdate();
		}
		else if (followTrans != null)
		{
			if (isOrbiting)
			{
				movement.OrbitTarget(followTrans.position);
				PlaySpinAudio();
			}
			else
			{
				distanceVector = followTrans.position - base.transform.position;
				if (Vector2.SqrMagnitude(distanceVector) > orbitRadiusSquared)
				{
					movement.moveVector = distanceVector.normalized;
					movement.MoveToMoveVector();
				}
				else
				{
					isOrbiting = true;
					movement.InitOrbitAngle(-distanceVector.normalized);
				}
			}
		}
		Transform transform = trailTrans;
		Vector2 vector;
		if (isOrbiting)
		{
			vector = Globals.GetPerpendicular(movement.orbitVector);
		}
		else
		{
			vector = ((!targetHit) ? movement.moveVector : moveVector);
		}
		transform.localEulerAngles = Globals.GetRotationVector(vector);
	}

	public override void HandleCollision(Collider2D other)
	{
		if (!(other.transform.parent != null) || IsParentObject(other.gameObject))
		{
			return;
		}
		targetHit = true;
		isOrbiting = false;
		if (impactAudioID != string.Empty)
		{
			SoundManager.PlayAudioWithDistance(impactAudioID, transform.position);
		}
		ricochetCounter++;
		if (ricochetCounter >= ricochetAmount || calculatedDamage == 0)
		{
			ResetProjectile();
			return;
		}
		TargetsHitList.Add(other.transform.parent.gameObject);
		nextTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, ricochetRadius, playerTagOnly: false, TargetsHitList, null, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
		if (nextTargetInfo == null)
		{
			targetHit = false;
			TargetsHitList.Clear();
			return;
		}
		ChaosStopwatch.Refresh(flyStopwatchID, flyTime);
		moveVector = (nextTargetInfo.hurtBoxPosition - transform.position).normalized;
		attackBox.atkInfo.knockbackOverwrite = true;
		attackBox.knockbackOverwriteVector = moveVector;
		isPointedAtMoveVector = false;
	}

	public override void ResetProjectile()
	{
		base.ResetProjectile();
		if (spinAudio != null)
		{
			spinAudio.Stop();
		}
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, transform.position);
	}

	private void PlaySpinAudio()
	{
		spinAudio = SoundManager.PlayIfNotPlaying("LightningPinball", spinAudio, followTrans, useStdPitchOverride: false);
	}
}
