	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ShockSpear.prefab"));

	public override void Start()
	{
		base.Start();
		if (ricochet)
		{
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(HandleEntityCollision));
			Attack attack2 = attackBox;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(HandleEntityCollision));
		}
		ricochetAtkLevel = attackBox.atkInfo.skillLevel + 1;
		SetMode();
		lightningEmitter = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		lightningEmitter.reqFollowTrans = true;
		ParticleEffect particleEffect = lightningEmitter;
		float? emissionRate = 10f;
		Vector3? position = wallCollider.transform.position;
		Transform followTransform = wallCollider.transform;
		particleEffect.Play(emissionRate, position, null, null, followTransform);
	}

	public override void ResetProjectile()
	{
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(20, transform.position);
		SoundManager.PlayAudioWithDistance("IonSpike", transform.position);
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(HandleEntityCollision));
		base.ResetProjectile();
	}

	public void HandleEntityCollision(Entity hitEntity)
	{
		if (hitEntity == null)
		{
			return;
		}
		if (!targetHit)
		{
			targetHit = true;
			SoundManager.PlayAudioWithDistance("IonSpike", transform.position, null, 24f, -1f, 1.2f);
			SetMode("Ricochet");
			projectileLight.SetActive(value: false);
			lastHitEntity = hitEntity;
			targetHitPosition = hitEntity.hurtBoxTransform.position;
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, targetHitPosition);
			return;
		}
		if (lastHitEntity != null)
		{
			targetHitPosition = lastHitEntity.hurtBoxTransform.position;
		}
		PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(targetHitPosition, hitEntity.hurtBoxTransform.position);
		lastHitEntity = hitEntity;
		targetHitPosition = hitEntity.hurtBoxTransform.position;
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(10, targetHitPosition);
		if (!ricochetCalled)
		{
			ricochetCalled = true;
			attackBox.ChangeAttackInfoLevel(ricochetAtkLevel);
		}
	}

	public void SetMode(string mode = "Idle")
	{
		switch (mode)
		{
		case "Idle":
			attackBox.enabled = false;
			wallCollider.enabled = false;
			projectileSpriteRenderer.enabled = true;
			break;
		case "Flying":
			attackBox.enabled = true;
			wallCollider.enabled = true;
			projectileSpriteRenderer.enabled = true;
			break;
		case "Ricochet":
			wallCollider.enabled = false;
			projectileSpriteRenderer.enabled = false;
			lightningEmitter.Stop();
			ignoreReflect = true;
			ignoreNegate = true;
			ignoreProjectileCollisions = true;
			moveSpeed *= 1.25f;
			break;
		}
	}
}
