public virtual void OnBoomerangReturn()
{
	if (attackBox != null && resetAttackOnBoomerangReturn)
	{
		attackBox.gameObject.SetActive(value: false);
		UpdateCalculatedDamage(initDamageOverride: true);
	}
}

public virtual void HandleBoomerang()
{
	if (parentObject != null)
	{
		moveVector = (parentObject.transform.position - transform.position).normalized;
	}
}

public virtual void OnProjectileCollision(Collider2D other, Projectile otherProjectile, bool doCalculations = true)
{
	if (doCalculations)
	{
		if (!alwaysWinCollision && !otherProjectile.alwaysWinCollision)
		{
			calcDamageDiff = calculatedDamage - otherProjectile.calculatedDamage;
			otherProjectile.calculatedDamage = Mathf.Max(0, otherProjectile.calculatedDamage - calculatedDamage);
			calculatedDamage = Mathf.Max(0, calcDamageDiff);
		}
		else
		{
			if (alwaysWinCollision)
			{
				otherProjectile.calculatedDamage = 0;
			}
			if (otherProjectile.alwaysWinCollision)
			{
				calculatedDamage = 0;
			}
		}
		otherProjectile.OnProjectileCollision(other, this, doCalculations: false);
	}
	if (calculatedDamage < 10 && (!alwaysWinCollision || otherProjectile.alwaysWinCollision))
	{
		calculatedDamage = 0;
		HandleCollision(other);
	}
	calcDamageActual = Mathf.CeilToInt((float)calculatedDamage / projectileCollisionModifier);
	attackBox.damageOverride = ((projectileStatData == null || projectileStatData.GetValue<int>("damage") <= calcDamageActual) ? (-1) : calcDamageActual);
	collidedProjectiles.Add(otherProjectile);
	SoundManager.PlayAudioWithDistance("ImpactNegate", transform.position);
}

public virtual void HandleWallCollision(Collider2D other)
{
	if (wallCollider != null)
	{
		PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, wallCollider.transform.position, wallCollider.transform.position);
	}
	else
	{
		PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, transform.position, transform.position);
	}
	if (!goThroughWalls)
	{
		if (boomerang)
		{
			ChaosStopwatch.Stop(flyStopwatchID);
		}
		else
		{
			ResetProjectile();
		}
	}
	if (globalProjectileWallCollisionEvents != null)
	{
		globalProjectileWallCollisionEvents(this);
	}
	if (wallCollisionEvents != null)
	{
		wallCollisionEvents(this);
	}
	HandleCollision(other);
}

public virtual void HandleCollision(Collider2D other)
{
	if (!(other.transform.parent != null) || IsParentObject(other.gameObject))
	{
		return;
	}
	if (impactAudioID != string.Empty)
	{
		SoundManager.PlayAudioWithDistance(impactAudioID, transform.position);
	}
	if (disableOnHit || calculatedDamage == 0)
	{
		flagForReset = true;
	}
	else if (returnOnHit)
	{
		ChaosStopwatch.Stop(flyStopwatchID);
	}
	else if (ricochet && ricochetAmount > 0 && !boomerangReturning)
	{
		ricochetCounter++;
		boomerangReturning = false;
		TargetsHitList.Add(other.transform.parent.gameObject);
		nextTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, ricochetRadius, playerTagOnly: false, TargetsHitList, null, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
		if (ricochetCounter >= ricochetAmount || nextTargetInfo == null)
		{
			ChaosStopwatch.Stop(flyStopwatchID);
			ricochetCounter = 0;
			return;
		}
		OnRicochet();
		ChaosStopwatch.Refresh(flyStopwatchID, flyTime);
		moveVector = (nextTargetInfo.hurtBoxPosition - transform.position).normalized;
		isPointedAtMoveVector = false;
	}
}

public virtual void ResetProjectile()
{
	ChaosStopwatch.Stop(flyStopwatchID);
	ChaosStopwatch.Stop(lifeStopwatchID);
	if (particleEffectOnReset && particleEffectName != null && particleEffectName != string.Empty)
	{
		PoolManager.GetPoolItem<ParticleEffect>(particleEffectName).Emit(particleEmitCount, transform.position + particleEmitOffset);
	}
	if (projectileSprite != null)
	{
		projectileSprite.transform.rotation = Quaternion.identity;
	}
	boomerangReturning = false;
	flagForReset = false;
	forcedReturn = false;
	if (gameObject != null)
	{
		if (destroyOnDisable)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
		else
		{
			gameObject.SetActive(value: false);
		}
	}
}

public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
{
	public bool useCastBar = true;

	public int maxCharge = 10;

	public int minCharge = 5;

	public float chargeTime = 0.2f;

	public float calcChargeTime;

	public int chargeStopwatchID;

	public bool fullyCharged;

	public int postStopwatchID;

	public AudioSource chargeAudioSource;

	public string chargeAudioID = string.Empty;

	public bool ignoreAudioIsPlaying;

	public bool lowerChargeTimeOnEmpower = true;

	public override void OnEnter()
	{
		base.OnEnter();
		calcChargeTime = ((!lowerChargeTimeOnEmpower || !IsEmpowered) ? chargeTime : (chargeTime * 0.5f));
		fullyCharged = maxCharge - minCharge <= 0;
		if (useCastBar && !fullyCharged)
		{
			parent.hud.castBar.StartCast(ChaosStopwatch.Begin(calcChargeTime * (float)(maxCharge - minCharge)), givenStatus: true);
		}
		PlayChargeEffects();
	}

	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!fullyCharged)
		{
			switch (ChaosStopwatch.CheckInterval(chargeStopwatchID))
			{
			case StopwatchState.Ready:
				PlayChargeEffects();
				AddProjectileCharge();
				break;
			case StopwatchState.Done:
				fullyCharged = true;
				postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
				break;
			}
		}
		else
		{
			HandlePostStopwatch();
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}

	public override void OnExit()
	{
		base.OnExit();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}

	public override Projectile CreateHoldProjectile()
	{
		chargeStopwatchID = ChaosStopwatch.Begin(calcChargeTime, useInterval: true, calcChargeTime, maxCharge - minCharge);
		return base.CreateHoldProjectile();
	}

	public virtual void HandlePostStopwatch()
	{
		if (ChaosStopwatch.Check(postStopwatchID))
		{
			postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
			PlayChargeEffects();
		}
	}

	public virtual void PlayChargeEffects()
	{
		if (!(chargeAudioID == string.Empty))
		{
			if (ignoreAudioIsPlaying)
			{
				StopChargeAudio();
			}
			if (currentProjectile != null)
			{
				chargeAudioSource = SoundManager.PlayIfNotPlaying(chargeAudioID, chargeAudioSource, currentProjectile.transform);
			}
		}
	}

	public void StopChargeAudio()
	{
		if (chargeAudioSource != null)
		{
			chargeAudioSource.Stop();
		}
	}

	public virtual void AddProjectileCharge()
	{
	}
}

